def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-i", dest="input")
    parser.add_argument("-o", "--output-dir", dest="output_dir")
    parser.add_argument("-m", "--make-mod", action="store_true")
    parser.add_argument("--target", dest="target", default="cortex-m")
    args, _ = parser.parse_known_args()

    if not args.input: sys.exit(0)

    print("[INFO  svd2rust] Parsing device from SVD file", file=sys.stderr)
    tree = ET.parse(args.input)
    print("[INFO  svd2rust] Rendering device", file=sys.stderr)

    device = tree.getroot()
    device_name = device.findtext("name")

    output_dir = args.output_dir or "."
    os.makedirs(output_dir, exist_ok=True)
    output_path = os.path.join(output_dir, "mod.rs" if args.make_mod else "lib.rs")

    interrupts = []
    for peripheral in device.findall(".//peripheral"):
        for interrupt in peripheral.findall("interrupt"):
            name = interrupt.findtext("name")
            value = interrupt.findtext("value")
            desc = interrupt.findtext("description")
            interrupts.append({"name": name, "value": int(value), "description": desc})
    interrupts.sort(key=lambda x: x["value"])

    with open(output_path, "w") as f:
        f.write(f'# ! [doc = "Peripheral access API for {device_name} microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust"] ')
        if not args.make_mod:
            f.write('# ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))] ')
        f.write('\n')
        f.write(BOILERPLATE_PRE_INTERRUPT)

        # Interrupts
        if args.target == "cortex-m":
            if interrupts:
                f.write('#[cfg (feature = "rt")] extern "C" { ')
                for intr in interrupts:
                    f.write(f'fn {intr["name"]} () ; ')
                f.write('} #[doc (hidden)] #[repr (C)] pub union Vector { _handler : unsafe extern "C" fn () , _reserved : u32 , } ')
                f.write(f'#[cfg (feature = "rt")] #[doc (hidden)] #[link_section = ".vector_table.interrupts"] #[no_mangle] pub static __INTERRUPTS : [Vector ; {interrupts[-1]["value"] + 1}] = [ ')
                last_val = -1
                for intr in interrupts:
                    for _ in range(last_val + 1, intr["value"]):
                        f.write('Vector { _reserved : 0 } , ')
                    f.write(f'Vector {{ _handler : {intr["name"]} }} , ')
                    last_val = intr["value"]
                f.write('] ; ')

            f.write('#[doc = r"Enumeration of all the interrupts."] #[derive (Copy , Clone , Debug , PartialEq , Eq)] #[repr (u16)] pub enum Interrupt { ')
            for intr in interrupts:
                doc = f'{intr["value"]} - {format_doc(intr["description"])}' if intr["description"] else str(intr["value"])
                f.write(f'#[doc = "{doc}"] {intr["name"]} = {intr["value"]} , ')
            f.write('} unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt { #[inline (always)] fn number (self) -> u16 { match self { ')
            for intr in interrupts:
                f.write(f'Interrupt :: {intr["name"]} => {intr["value"]} , ')
            f.write('} } } \n')
        else:
            f.write('#[doc = r"Enumeration of all the interrupts."] #[derive (Copy , Clone , Debug , PartialEq , Eq)] #[repr (u16)] pub enum Interrupt { } \n')

        # Peripherals
        peripherals_info = []
        for peripheral in device.findall(".//peripheral"):
            p_name = peripheral.findtext("name")
            p_base = peripheral.findtext("baseAddress")
            p_desc = peripheral.findtext("description") or p_name
            p_type = pascal_case(p_name)
            p_snake = snake_case(p_name)
            peripherals_info.append((p_snake, p_type, p_name))

            f.write(f'#[doc = "{p_name}"] pub type {p_type} = crate :: Periph < {p_type}Spec > ; pub struct {p_type}Spec ; impl crate :: PeripheralSpec for {p_type}Spec {{ type RB = {p_snake} :: RegisterBlock ; const ADDRESS : usize = {p_base} ; const NAME : & \'static str = "{p_type}" ; }} ')
            f.write(f'#[doc = "{p_name}"] pub mod {p_snake} {{ #[allow (unused_imports)] use super :: {{ BitReader , BitWriter , FieldReader , FieldWriter , RegisterSpec , Readable , Writable , Resettable , Unsafe }} ; #[repr (C)] #[doc = "Register block"] pub struct RegisterBlock {{ ')

            regs = []
            for reg in peripheral.findall(".//register"):
                r_name = reg.findtext("name")
                r_offset = reg.findtext("addressOffset")
                r_desc = reg.findtext("description") or ""
                r_size = reg.findtext("size") or device.findtext("size") or "32"
                r_snake = snake_case(r_name)
                r_type = pascal_case(r_name)
                regs.append({"name": r_name, "offset": r_offset, "desc": r_desc, "size": r_size, "snake": r_snake, "type": r_type, "node": reg})
                f.write(f'{r_snake} : {r_type} , ')
            f.write('} impl RegisterBlock { ')
            for r in regs:
                f.write(f'#[doc = "{r["offset"]} - {format_doc(r["desc"])}"] #[inline (always)] pub const fn {r["snake"]} (& self) -> & {r["type"]} {{ & self . {r["snake"]} }} } ')

