    s = s.replace("[%s]", "").replace("%s", "")
    s = re.sub(r'(.)([A-Z][a-z]+)', r'\1_\2', s)
    s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s).lower()
    s = re.sub(r'[^a-z0-9]', '_', s)
    s = re.sub(r'_+', '_', s)
    return s.strip('_')

def format_doc(doc):
    if not doc: return ""
    return doc.replace('\n', ' ').strip()

