def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-i", dest="input")
    parser.add_argument("-o", "--output-dir", dest="output_dir")
    parser.add_argument("-m", "--make-mod", action="store_true")
    parser.add_argument("--target", dest="target", default="cortex-m")
    args, _ = parser.parse_known_args()

    if not args.input: sys.exit(0)

    print("[INFO  svd2rust] Parsing device from SVD file", file=sys.stderr)
    tree = ET.parse(args.input)
    print("[INFO  svd2rust] Rendering device", file=sys.stderr)

    device = tree.getroot()
    device_name = device.findtext("name")

    output_dir = args.output_dir or "."
    os.makedirs(output_dir, exist_ok=True)
    output_path = os.path.join(output_dir, "mod.rs" if args.make_mod else "lib.rs")

    interrupts = []
    for peripheral in device.findall(".//peripheral"):
        for interrupt in peripheral.findall("interrupt"):
            name = interrupt.findtext("name")
            value = interrupt.findtext("value")
            desc = interrupt.findtext("description")
            interrupts.append({"name": name, "value": int(value), "description": desc})
    interrupts.sort(key=lambda x: x["value"])

    with open(output_path, "w") as f:
        f.write('# ! [doc = "Peripheral access API for ' + device_name + ' microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust"] ')
        if not args.make_mod:
            f.write('# ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))] ')
        f.write('\n')
        f.write(BOILERPLATE)

        if args.target == "cortex-m":
            if interrupts:
                f.write('#[cfg (feature = "rt")] extern "C" { ')
                for intr in interrupts: f.write('fn ' + intr["name"] + ' () ; ')
                f.write('} #[doc (hidden)] #[repr (C)] pub union Vector { _handler : unsafe extern "C" fn () , _reserved : u32 , } ')
                f.write('#[cfg (feature = "rt")] #[doc (hidden)] #[link_section = ".vector_table.interrupts"] #[no_mangle] pub static __INTERRUPTS : [Vector ; ' + str(interrupts[-1]["value"] + 1) + '] = [ ')
                last_val = -1
                for intr in interrupts:
                    for _ in range(last_val + 1, intr["value"]): f.write('Vector { _reserved : 0 } , ')
                    f.write('Vector { _handler : ' + intr["name"] + ' } , ')
                    last_val = intr["value"]
                f.write('] ; ')
            f.write('#[doc = r"Enumeration of all the interrupts."] #[derive (Copy , Clone , Debug , PartialEq , Eq)] #[repr (u16)] pub enum Interrupt { ')
            for intr in interrupts:
                doc = (str(intr["value"]) + ' - ' + format_doc(intr["description"])) if intr["description"] else str(intr["value"])
                f.write('#[doc = "' + doc + '"] ' + intr["name"] + ' = ' + str(intr["value"]) + ' , ')
            f.write('} unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt { #[inline (always)] fn number (self) -> u16 { match self { ')
            for intr in interrupts: f.write('Interrupt :: ' + intr["name"] + ' => ' + str(intr["value"]) + ' , ')
            f.write('} } } \n')
        else:
            f.write('#[doc = r"Enumeration of all the interrupts."] #[derive (Copy , Clone , Debug , PartialEq , Eq)] #[repr (u16)] pub enum Interrupt { } \n')

        peripherals_info = []
        for peripheral in device.findall(".//peripheral"):
            p_name = peripheral.findtext("name")
            p_base = peripheral.findtext("baseAddress")
            p_type, p_snake = pascal_case(p_name), snake_case(p_name)
            peripherals_info.append((p_snake, p_type, p_name))
            f.write('#[doc = "' + p_name + '"] pub type ' + p_type + ' = crate :: Periph < ' + p_type + 'Spec > ; pub struct ' + p_type + 'Spec ; impl crate :: PeripheralSpec for ' + p_type + 'Spec { type RB = ' + p_snake + ' :: RegisterBlock ; const ADDRESS : usize = ' + str(p_base) + ' ; const NAME : & \'static str = "' + p_type + '" ; } ')
            f.write('#[doc = "' + p_name + '"] pub mod ' + p_snake + ' { #[allow (unused_imports)] use super :: { BitReader , BitWriter , FieldReader , FieldWriter , RegisterSpec , Readable , Writable , Resettable , Unsafe } ; #[repr (C)] #[doc = "Register block"] pub struct RegisterBlock { ')
            regs = []
            for reg in peripheral.findall(".//register"):
                r_name = reg.findtext("name")
                r_offset = reg.findtext("addressOffset")
                r_desc = reg.findtext("description") or ""
                r_size = reg.findtext("size") or device.findtext("size") or "32"
                r_snake, r_type = snake_case(r_name), pascal_case(r_name)
                regs.append({"name": r_name, "offset": r_offset, "desc": r_desc, "size": r_size, "snake": r_snake, "type": r_type, "node": reg})
                f.write(r_snake + ' : ' + r_type + ' , ')
            f.write('} impl RegisterBlock { ')
            for r in regs:
                f.write('#[doc = "' + r["offset"] + ' - ' + format_doc(r["desc"]) + '"] #[inline (always)] pub const fn ' + r["snake"] + ' (& self) -> & ' + r["type"] + ' { & self . ' + r["snake"] + ' } ')
            f.write('} ')
            for r in regs:
                f.write('#[doc = "' + r["name"] + ' (rw) register accessor: ' + format_doc(r["desc"]) + '\\n\\nYou can [`read`](crate::Reg::read) this register and get [`' + r["snake"] + '::R`]. You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`' + r["snake"] + '::W`]. You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\\n\\nFor information about available fields see [`mod@' + r["snake"] + '`] module"] #[doc (alias = "' + r["name"] + '")] pub type ' + r["type"] + ' = crate :: Reg < ' + r["snake"] + ' :: ' + r["type"] + 'Spec > ; #[doc = "' + format_doc(r["desc"]) + '"] pub mod ' + r["snake"] + ' { #[allow (unused_imports)] use super :: { BitReader , BitWriter , FieldReader , FieldWriter , RegisterSpec , Readable , Writable , Resettable , Unsafe } ; #[doc = "Register `' + r["name"] + '` reader"] pub type R = crate :: R < ' + r["type"] + 'Spec > ; #[doc = "Register `' + r["name"] + '` writer"] pub type W = crate :: W < ' + r["type"] + 'Spec > ; ')
                fields = []
                for field in r["node"].findall(".//field"):
                    f_name = field.findtext("name")
                    f_offset, f_width = int(field.findtext("bitOffset")), int(field.findtext("bitWidth"))
